<script>
import BaseComponent from '@primevue/core/basecomponent';
import InputColorSliderStyle from 'primevue/inputcolorslider/style';

export default {
    name: 'BaseInputColorSlider',
    extends: BaseComponent,
    props: {
        channel: {
            type: String,
            default: 'hue'
        },
        orientation: {
            type: String,
            default: 'horizontal'
        },
        disabled: {
            type: Boolean,
            default: false
        },
        as: {
            type: [String, Object, Function],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: InputColorSliderStyle,
    provide() {
        return {
            $pcInputColorSlider: this,
            $parentInstance: this
        };
    }
};
</script>
